// GROUND TRUTH for `math.ts` — every row here was produced by COMPILING AND
// RUNNING the program's own `solana/tegridy-amm/programs/tegridy-launch/src/curve.rs`
// on the host. Nothing below was computed in JavaScript.
//
// WHY
// `math.ts` is a hand transcription of Rust into TypeScript. A transcription that
// is only reviewed by eye is not verified — and a rounding direction flipped in
// one branch is invisible in review and silent in production: the user simply
// receives less than the UI promised. So the two implementations are compared
// against each other, on 3,815 cases, exactly.
//
// COVERAGE (counted from the rows below)
//   feeUp                  300  · quoteBuy               820
//   quoteSell              820  · lamportsUntilTarget    370
//   maxReachableRealSol    205  · graduationPriceRatioBps 665
//   continuityTarget       635
// Inputs are log-uniform over the full u64 magnitude range from a seeded
// xorshift64*, crossed with every fee in {0, 1, 25, 100, 300, 999, 1000, 1001,
// 9999, 10000} bps — i.e. either side of both `MAX_FEE_BPS` (1000) and
// `BPS_DENOMINATOR` (10000) — plus hand-picked degenerate reserves. Every error
// variant of every function appears, and so does the `None` branch of
// `lamports_until_target`.
//
// ⚠ WHY THE LAST TWO SECTIONS GREW (2026-08-01 consolidation)
// The first generation sampled `graduation_price_ratio_bps` and `continuity_target`
// from a NARROW window — `vs` ≤ 2^48, `vt`/`s` ≤ 2^56 — which caps `vs·(vt+s)` at
// ~2^105 and therefore never reached `u128::MAX`. Both functions hold u128
// intermediates that genuinely CAN exceed it on real u64 inputs, where curve.rs's
// `checked_mul` returns `Overflow`. That branch was unreachable from the fixture,
// the port was consequently unproven there — and it was WRONG: `math.ts` computed
// in unbounded `bigint` and returned a confident number where the program errors.
// e.g. graduationPriceRatioBps(2^64−1, 2^64−1, 2^64−1, 2^63, 0) is `Err(Overflow)`
// in Rust and used to return `ok(13333)` here. These sections now sample the full
// u64 range and pin the u128 ceiling from both sides.
//
// HOW TO REGENERATE (Windows dev box, no SBF toolchain needed — curve.rs is
// deliberately Solana-free so it builds with plain rustc, see curve.rs:1-3)
//
//   cd solana/tegridy-amm
//   cp programs/tegridy-launch/src/curve.rs /tmp/curve_pub.rs
//   # the generator calls `fee_up`, which is private in the original:
//   sed -i 's/^fn fee_up(/pub fn fee_up(/' /tmp/curve_pub.rs
//   diff /tmp/curve_pub.rs programs/tegridy-launch/src/curve.rs   # must be that ONE line
//   cp tools/gen_curve_vectors.rs /tmp/ && cd /tmp
//   rustc --edition 2021 -O -o gen gen_curve_vectors.rs && ./gen
//
// Then splice the output under this header. Keep the header.
//
// Generated 2026-08-01 against curve.rs at commit 3cc2b0ba, whose own
// `#[cfg(test)] mod tests` was run in the same session: 23 passed, 0 failed.

/**
 * One case: `[inputs, outputs]` on success, `[inputs, errorName]` on failure.
 * All numbers are decimal strings so the file survives JSON round-trips and no
 * value is silently truncated to a double. An EMPTY output array is Rust's
 * `Ok(None)` — used only by `lamportsUntilTarget`, where it means "already at
 * the target", which is a completely different thing from an error.
 */
export type CurveVector = readonly [inputs: readonly string[], expected: readonly string[] | string];

